mapper.select:
SELECT history_id, member_id, member_name, action_type, points, category, detail_reason, before_mileage, after_mileage, created_by, reg_dtm FROM mileage_history
AND UPPER(member_name) LIKE CONCAT('%', UPPER(#{name}), '%')
AND UPPER(member_id) LIKE CONCAT('%', UPPER(#{memberId}), '%')
AND action_type = #{actionType}
AND DATE(reg_dtm) >= #{fromDate}
AND DATE(reg_dtm) <= #{toDate}
ORDER BY reg_dtm DESC, history_id DESC
